using System;using System.Collections;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.XR;using UnityEngine.XR.Interaction.Toolkit.Inputs.Readers;using LighthouseKeepers.WatchDemo;using LighthouseKeepers.Gameplay.Interaction;using LighthouseKeepers.Core.Progression;
public class FlashlightGripCheck:MonoBehaviour {
 string folder;HandRig hand;List<string> checks=new();bool failed;MethodInfo late=typeof(HandRig).GetMethod("LateUpdate",BindingFlags.NonPublic|BindingFlags.Instance);
 public static object Run(string p){EditorUtility.audioMasterMute=true;var c=new GameObject("Flashlight grip acceptance").AddComponent<FlashlightGripCheck>();c.folder=p;return "started";}
 void Check(bool x,string s){checks.Add((x?"PASS ":"FAIL ")+s);failed|=!x;}
 void LateUpdate(){if(hand)late.Invoke(hand,null);}
 IEnumerator Start(){Directory.CreateDirectory(folder);var w=FindAnyObjectByType<WatchDemoController>();w.enabled=false;w.GetComponent<CrewCompanion>().SetCommand(CompanionCommand.Wait);w.GetComponent<QuestRenderQuality>().enabled=false;var rig=FindAnyObjectByType<Unity.XR.CoreUtils.XROrigin>();
 foreach(var m in rig.GetComponentsInChildren<UnityEngine.XR.Interaction.Toolkit.Inputs.XRInputModalityManager>(true))m.enabled=false;
 var studio=new GameObject("Grip inspection light (test only)").AddComponent<Light>();studio.type=LightType.Point;studio.range=3;studio.intensity=1.5f;studio.transform.position=new Vector3(-.3f,1.8f,-7.4f);
 foreach(var h in rig.GetComponentsInChildren<HandRig>(true))h.transform.parent.gameObject.SetActive(false);
 foreach(var node in new[]{XRNode.LeftHand,XRNode.RightHand}){
 hand=rig.GetComponentsInChildren<HandRig>(true).First(h=>h.Node==node);hand.transform.parent.gameObject.SetActive(true);foreach(var t in hand.transform.parent.GetComponents<UnityEngine.InputSystem.XR.TrackedPoseDriver>())t.enabled=false;hand.enabled=false;
 var data=(HandRig.Model)typeof(HandRig).GetField("data",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(hand);var bones=(Transform[])typeof(HandRig).GetField("bones",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(hand);for(int i=0;i<bones.Length;i++)bones[i].localRotation=data.poses[2].rotations[i];
 var d=hand.Direct;d.enabled=true;d.selectInput=new XRInputButtonReader("test grip",inputSourceMode:XRInputButtonReader.InputSourceMode.ManualValue);d.selectInput.QueueManualState(false,0);d.activateInput=new XRInputButtonReader("test trigger",inputSourceMode:XRInputButtonReader.InputSourceMode.ManualValue);d.activateInput.QueueManualState(false,0,false,true);
 var l=w.Lantern(node==XRNode.LeftHand?0:1);l.transform.SetPositionAndRotation(new Vector3(-1,1.35f,-8),Quaternion.identity);l.GetComponent<Rigidbody>().isKinematic=true;hand.transform.parent.rotation=Quaternion.identity;hand.transform.parent.position=l.transform.TransformPoint(FlashlightMesh.Handle);Physics.SyncTransforms();yield return new WaitForSeconds(.3f);d.selectInput.QueueManualState(true,1);yield return new WaitForSeconds(.4f);Check(l.Grab.isSelected,node+" actual direct grip selects flashlight");l.Grab.activated.AddListener(e=>File.AppendAllText(folder+"/trigger.log",node+" activated "+Time.time+" before "+w.State.Lanterns.Wick(l.Slot)+"\n"));l.Grab.deactivated.AddListener(e=>File.AppendAllText(folder+"/trigger.log",node+" deactivated "+Time.time+"\n"));
 var skin=hand.GetComponentInChildren<SkinnedMeshRenderer>();Check(Vector3.Distance(skin.transform.TransformPoint(FlashlightMesh.HandContact),l.transform.TransformPoint(FlashlightMesh.Handle))<.002f,node+" handle aligned with finger cavity");
 var baked=new Mesh();skin.BakeMesh(baked);int deep=0;float nearest=1;
 foreach(var vertex in baked.vertices){var v=l.transform.InverseTransformPoint(skin.transform.TransformPoint(vertex));if(v.y>-.065f&&v.y<.065f){float radial=new Vector2(v.x,v.z).magnitude;nearest=Mathf.Min(nearest,radial);if(radial<FlashlightMesh.GripRadius-.002f)deep++;}}
 Check(deep==0,node+" no hand vertices penetrate handle by more than 2mm ("+deep+", nearest "+nearest+")");Destroy(baked);
 var p=l.transform.position;Capture(p+new Vector3(.26f,.16f,.38f),p+Vector3.up*.03f,node+"-front.png");Capture(p+new Vector3(-.27f,.15f,-.38f),p+Vector3.up*.03f,node+"-back.png");Capture(p+new Vector3(.02f,.42f,-.12f),p,node+"-top.png");
 d.activateInput.QueueManualState(true,1);yield return new WaitForSeconds(.3f);Check(w.State.Lanterns.Wick(l.Slot)==LanternWick.High,node+" trigger goes directly to focused HIGH");d.activateInput.QueueManualState(false,0,false,true);yield return new WaitForSeconds(.5f);d.activateInput.QueueManualState(true,1,true,false);yield return new WaitForSeconds(.3f);Check(w.State.Lanterns.Wick(l.Slot)==LanternWick.Off,node+" second press turns OFF, no LOW stage");d.activateInput.QueueManualState(false,0,false,true);d.selectInput.QueueManualState(false,0);yield return new WaitForSeconds(.4f);Check(!l.Grab.isSelected,node+" release works");hand.transform.parent.position=Vector3.up*20;hand.transform.parent.gameObject.SetActive(false);
 }
 Destroy(studio.gameObject);File.WriteAllText(folder+"/grips.json",JsonUtility.ToJson(new Result{passed=!failed,checks=checks.ToArray()},true));hand=null;Destroy(gameObject);}
 void Capture(Vector3 p,Vector3 target,string file){var c=new GameObject("Evidence camera").AddComponent<Camera>();c.transform.position=p;c.transform.LookAt(target);c.fieldOfView=45;c.nearClipPlane=.02f;var rt=new RenderTexture(900,900,24);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(900,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,900,900),0,0);t.Apply();File.WriteAllBytes(folder+"/"+file,t.EncodeToPNG());RenderTexture.active=null;c.targetTexture=null;Destroy(c.gameObject);Destroy(rt);Destroy(t);}
 [Serializable]class Result{public bool passed;public string[] checks;}
}
